package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class CommandLine_hasOption_TriageGen0Test {

    private CommandLine commandLine;

    @Before
    public void setUp() {
        Map<String, String> options = new HashMap<>();
        commandLine = new CommandLine(options);
    }

    @Test
    public void testHasOption_ExistingOption() {
        commandLine.getOptions().add(new Option("opt1", true, "Option 1"));
        assertTrue(commandLine.hasOption("opt1"));
    }

    @Test
    public void testHasOption_NonExistingOption() {
        assertFalse(commandLine.hasOption("opt2"));
    }

    @Test
    public void testHasOption_EmptyString() {
        assertFalse(commandLine.hasOption(""));
    }

    @Test
    public void testHasOption_Null() {
        assertFalse(commandLine.hasOption(null));
    }

    @Test
    public void testHasOption_MultipleOptions() {
        commandLine.getOptions().add(new Option("opt1", true, "Option 1"));
        commandLine.getOptions().add(new Option("opt2", true, "Option 2"));
        assertTrue(commandLine.hasOption("opt1"));
        assertTrue(commandLine.hasOption("opt2"));
        assertFalse(commandLine.hasOption("opt3"));
    }

    @Test
    public void testHasOption_CaseSensitivity() {
        commandLine.getOptions().add(new Option("Opt1", true, "Option 1"));
        assertTrue(commandLine.hasOption("Opt1"));
        assertFalse(commandLine.hasOption("opt1"));
    }
}
